-- Rollback-only transaction/security tests. Run only against confirmed local CRA.
begin;
set local statement_timeout='30s';
create function pg_temp.check(label text, ok boolean) returns void language plpgsql as $$ begin
 if not coalesce(ok,false) then raise exception 'M15 check failed: %',label; end if;
end $$;
select pg_temp.check('state authority exists',to_regclass('public.organization_license_states') is not null);
select pg_temp.check('no browser state access',not has_table_privilege('authenticated','public.organization_license_states','select'));
select pg_temp.check('no browser admission access',not has_table_privilege('authenticated','public.organization_storage_admissions','insert'));
select pg_temp.check('state service RPC',has_function_privilege('service_role','public.m15_01_get_state(uuid,uuid)','execute'));
select pg_temp.check('state RPC browser denied',not has_function_privilege('authenticated','public.m15_01_get_state(uuid,uuid)','execute'));
create function pg_temp.m15_fail_audit() returns trigger language plpgsql as $$ begin if new.action='licensing.activation' and new.after_redacted->>'licenseArtifactDigest'=repeat('f',64) then raise exception 'M15 forced audit failure';end if;return new;end $$;
create trigger m15_forced_audit_failure before insert on public.audit_logs for each row execute function pg_temp.m15_fail_audit();
do $$ declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();u uuid;a jsonb;r jsonb;k uuid:=gen_random_uuid();op uuid:=gen_random_uuid();path_id uuid:=gen_random_uuid();license_digest text:=encode(extensions.digest('fixture.valid','sha256'),'hex');begin
 select id into strict u from public.users where is_active and email_verified_at is not null limit 1;
 insert into public.organizations(id,name,slug)values(o,'M15 rollback fixture','m15-'||o);
 insert into public.organizations(id,name,slug)values(o2,'M15 foreign storage fixture','m15-foreign-'||o2);
 insert into public.organization_members(organization_id,user_id,role)values(o,u,'owner');
 insert into storage.objects(bucket_id,name,metadata)values('product-imports',o2::text||'/'||gen_random_uuid()::text||'/source.csv',jsonb_build_object('size',1));
 a:=jsonb_build_object('schemaVersion',1,'licenseId',gen_random_uuid(),'sequence',1,'issuer','fixture','organizationId',o,'instanceId',gen_random_uuid(),'issuedAt',clock_timestamp()-interval '1 day','startsAt',clock_timestamp()-interval '1 day','expiresAt',clock_timestamp()+interval '1 day','graceDays',30,'entitlements',jsonb_build_array('products','administration','evidence'),'limits',jsonb_build_object('activeMembers',2,'products',1,'storageBytes',100));
 insert into storage.objects(bucket_id,name)values('licence-artifacts',o::text||'/'||license_digest||'.jws');
 r:=public.m15_01_activate(o,u,'fixture.valid',license_digest,a,0,k,repeat('b',64),null,o::text||'/'||license_digest||'.jws');
 perform pg_temp.check('activation',r->>'outcome'='activated');
 perform pg_temp.check('foreign orphan does not poison storage readiness',(select storage_accounting_ready and public.m15_01_storage_accounting_ready(o) from public.organization_license_states where organization_id=o));
 r:=public.m15_01_activate(o,u,'fixture.valid',license_digest,a,0,k,repeat('b',64),null);
 perform pg_temp.check('same command replay',r->>'outcome'='replayed');
 r:=public.m15_01_activate(o,u,'fixture.changed',repeat('c',64),a,0,k,repeat('c',64),null);
 perform pg_temp.check('changed command conflicts',r->>'outcome'='conflict');
 r:=public.m15_01_activate(o,u,'tampered',repeat('d',64),null,1,gen_random_uuid(),repeat('e',64),'invalid_signature');
 perform pg_temp.check('invalid replacement recorded',r->>'outcome'='rejected');
 perform pg_temp.check('old valid artifact survives',(select artifact_digest=license_digest and version=1 from public.organization_license_states where organization_id=o));
 perform pg_temp.check('proof sync',public.m15_01_checkpoint_verification(o,u,1,license_digest,true,a->'entitlements',1,repeat('9',64),clock_timestamp())->>'outcome'='updated');
 perform pg_temp.check('history durable',jsonb_array_length(public.m15_01_history(o,u,20,null)->'items')=2);
 perform pg_temp.check('foreign scope denied',public.m15_01_get_state(gen_random_uuid(),u)->>'outcome'='forbidden');
 insert into storage.objects(bucket_id,name)values('licence-artifacts',o::text||'/'||repeat('f',64)||'.jws');
 begin
 perform public.m15_01_activate(o,u,'fixture.next',repeat('f',64),jsonb_set(a,'{sequence}','2'),1,gen_random_uuid(),repeat('f',64),null,o::text||'/'||repeat('f',64)||'.jws');
 raise exception 'M15 audit failure did not rollback';
 exception when raise_exception then if sqlerrm<>'M15 forced audit failure' then raise;end if;end;
 perform pg_temp.check('audit failure preserves old licence',(select artifact_digest=license_digest and version=1 from public.organization_license_states where organization_id=o));
 r:=public.m15_01_reserve_storage(o,u,op,'product-imports',o::text||'/'||path_id::text||'/source.csv',101,repeat('1',64),clock_timestamp()+interval '10 minutes','products',null,'text/csv');
 perform pg_temp.check('storage cap rejects',r->>'outcome'='quota_exceeded');
 r:=public.m15_01_reserve_storage(o,u,op,'product-imports',o::text||'/'||path_id::text||'/source.csv',50,repeat('1',64),clock_timestamp()+interval '10 minutes','products',null,'text/csv');
 perform pg_temp.check('storage reserves',r->>'outcome'='reserved');
 perform pg_temp.check('reservation counts separately',public.m15_01_usage(o)->>'storageReservedBytes'='50' and public.m15_01_usage(o)->>'storageBytes'='0');
 r:=public.m15_01_reserve_storage(o,u,gen_random_uuid(),'product-imports',o::text||'/'||path_id::text||'/source.csv',50,repeat('2',64),clock_timestamp()+interval '10 minutes','products',null,'text/csv');
 perform pg_temp.check('lost-response reissue preserves operation',r->>'outcome'='replayed' and r->>'operationId'=op::text);
 perform pg_temp.check('reissue does not charge twice',public.m15_01_usage(o)->>'storageReservedBytes'='50');
 perform pg_temp.check('old URL revoked',public.m15_01_claim_storage_upload(op,repeat('1',64))->>'outcome'='conflict');
 perform pg_temp.check('claim single-use',public.m15_01_claim_storage_upload(op,repeat('2',64))->>'outcome'='claimed');
 perform pg_temp.check('second PUT conflicts',public.m15_01_claim_storage_upload(op,repeat('2',64))->>'outcome'='conflict');
 perform pg_temp.check('upload live authority',public.m15_01_validate_storage_upload(op,repeat('2',64))->>'outcome'='authorized');
 begin
 update public.users set is_active=false where id=u;
 perform pg_temp.check('revoked uploader blocked before publication',public.m15_01_validate_storage_upload(op,repeat('2',64))->>'outcome'='forbidden');
 perform pg_temp.check('revoked activation blocked',public.m15_01_activate(o,u,'tampered',repeat('d',64),null,1,gen_random_uuid(),repeat('e',64),'invalid_signature')->>'outcome'='forbidden');
 raise exception using errcode='P0002',message='M15 revoked-user subtransaction rollback';
 exception when no_data_found then null;end;
 perform pg_temp.check('prepublication hash bound',public.m15_01_prepare_storage_publication(op,repeat('2',64),repeat('3',64))->>'outcome'='authorized');
 perform pg_temp.check('completion requires actual object',public.m15_01_complete_storage(o,u,op,repeat('2',64),50)->>'outcome'='conflict');
 insert into storage.objects(bucket_id,name,metadata,user_metadata)values('product-imports',o::text||'/'||path_id::text||'/source.csv',jsonb_build_object('size',50),jsonb_build_object('sha256',repeat('3',64),'operationId',op));
 perform pg_temp.check('bounded completion refuses truncation',public.m15_01_complete_storage(o,u,op,repeat('2',64),49)->>'outcome'='conflict');
 perform pg_temp.check('bounded completion exact',public.m15_01_complete_storage(o,u,op,repeat('2',64),50)->>'outcome'='completed');
 perform pg_temp.check('completion retry',public.m15_01_complete_storage(o,u,op,repeat('2',64),50)->>'outcome'='replayed');
 perform pg_temp.check('completed bytes replace reservation',public.m15_01_usage(o)->>'storageReservedBytes'='0' and public.m15_01_usage(o)->>'storageBytes'='50');
 perform pg_temp.check('configuration same-revision conflict',public.m15_01_checkpoint_verification(o,u,1,license_digest,true,a->'entitlements',1,repeat('8',64),clock_timestamp())->>'outcome'='conflict');
 perform public.m15_01_assert_customer_write(o,'products');
 update public.organization_license_states set verified_claims=jsonb_set(verified_claims,'{expiresAt}',to_jsonb((clock_timestamp()-interval '31 days')::text)) where organization_id=o;
 begin perform pg_temp.check('configuration same-revision conflict',public.m15_01_checkpoint_verification(o,u,1,license_digest,true,a->'entitlements',1,repeat('8',64),clock_timestamp())->>'outcome'='conflict');
 perform public.m15_01_assert_customer_write(o,'products');raise exception 'expired licence allowed';exception when insufficient_privilege then null;end;
end $$;
rollback;
